                <th className="py-3 px-4">Entity</th>
                <th className="py-3 px-4">Issue</th>
                <th className="py-3 px-4">Retries</th>
                <th className="py-3 px-4">Timestamp</th>
                <th className="py-3 px-4 last:pr-0 text-right">Action</th>
