"use client";
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { applicationsApi, jobsApi } from "@/lib/api";
import { useParams, useRouter } from "next/navigation";
import { cn, getMatchBadgeClass, getStatusClass, getStatusLabel, formatDateTime, formatDate } from "@/lib/utils";
import Link from "next/link";
import { toast } from "sonner";
import { ArrowLeft, ExternalLink, Calendar, Star, Edit3, Building, Mail, AlignLeft, ShieldAlert, Users, ChevronRight, Briefcase, FileText, Clock , Loader2} from "lucide-react";

export default function ApplicationDetailPage() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const qc = useQueryClient();
  const [isEditing, setIsEditing] = useState(false);
  const [form, setForm] = useState({ status: "", recruiter_name: "", recruiter_email: "", interview_date: "", offer_salary: "", notes: "" });

  const { data: app, isLoading } = useQuery({
    queryKey: ["application", id],
    queryFn: () => applicationsApi.get(id).then((r) => r.data),
  });

  const { data: job } = useQuery({
    queryKey: ["job", app?.job_id],
    queryFn: () => jobsApi.get(app.job_id).then((r) => r.data),
    enabled: !!app?.job_id,
  });

  const updateMut = useMutation({
    mutationFn: (data: any) => applicationsApi.updateStatus(id, data),
    onSuccess: () => { toast.success("Updated!"); setIsEditing(false); qc.invalidateQueries({ queryKey: ["application", id] }); },
  });

  const starMut = useMutation({
    mutationFn: () => applicationsApi.star(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: ["application", id] }),
  });

  if (isLoading) return <div className="skeleton h-96 w-full rounded-xl" />;

  const handleEdit = () => {
    setForm({
      status: app.status,
      recruiter_name: app.recruiter_name ?? "",
      recruiter_email: app.recruiter_email ?? "",
      interview_date: app.interview_date ? new Date(app.interview_date).toISOString().slice(0, 16) : "",
      offer_salary: app.offer_salary?.toString() ?? "",
      notes: app.notes ?? "",
    });
    setIsEditing(true);
  };

  const submitEdit = (e: React.FormEvent) => {
    e.preventDefault();
    updateMut.mutate({
      ...form,
      offer_salary: form.offer_salary ? parseInt(form.offer_salary) : null,
      interview_date: form.interview_date ? new Date(form.interview_date).toISOString() : null,
    });
  };

  return (
    <div className="space-y-6">
      <button onClick={() => router.back()} className="flex items-center gap-2 text-muted-foreground hover:text-foreground text-sm">
        <ArrowLeft className="w-4 h-4" /> Back
      </button>

      <div className="-card p-6">
        <div className="flex items-start justify-between">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <span className={cn("px-2.5 py-1 text-[10px] uppercase tracking-wider font-bold rounded border", getStatusClass(app?.status))}>
                {getStatusLabel(app?.status)}
              </span>
              {app?.match_score_at_apply && (
                <span className={cn("px-2 py-0.5 text-xs font-bold rounded", getMatchBadgeClass(app.match_score_at_apply))}>
                  {Math.round(app.match_score_at_apply)}% Match
                </span>
              )}
            </div>
            <h1 className="text-2xl font-bold tracking-tight text-white mb-1">{app?.job_title_snapshot ?? job?.title}</h1>
            <p className="text-muted-foreground mt-1 flex items-center gap-2">
              <Building className="w-4 h-4" /> {app?.company_snapshot ?? job?.company_name}
            </p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => starMut.mutate()} className="p-2  rounded-lg hover:bg-[#1c1c1e] disabled:opacity-50 text-amber-400">
              <Star className={cn("w-5 h-5", app?.is_starred ? "fill-amber-400" : "")} />
            </button>
            <button onClick={handleEdit} className="flex items-center gap-2 px-4 py-2  rounded-lg text-sm hover:bg-[#1c1c1e] transition-colors">
              <Edit3 className="w-4 h-4" /> Update
            </button>
            {job?.source_url && (
              <a href={job.source_url} target="_blank" rel="noopener noreferrer" className="p-2  rounded-lg hover:bg-[#1c1c1e] text-muted-foreground">
                <ExternalLink className="w-5 h-5" />
              </a>
            )}
          </div>
        </div>

        {/* Bot Info if failed */}
        {app?.status === "failed" && app?.bot_error && (
          <div className="mt-6 p-4 bg-red-500/10 border border-red-500/30 rounded-xl flex items-start gap-3">
            <ShieldAlert className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-semibold text-red-400">Bot execution failed (Retry {app.retry_count}/3)</p>
              <p className="text-xs text-red-400/80 mt-1 font-mono bg-red-500/10 p-2 rounded">{app.bot_error}</p>
            </div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Col - Details & Editing */}
        <div className="lg:col-span-2 space-y-6">
          {isEditing ? (
            <form onSubmit={submitEdit} className="-card p-6 space-y-4">
              <h3 className="font-semibold mb-4">Edit Details</h3>
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2 sm:col-span-1">
                  <label className="block text-xs text-muted-foreground mb-1">Status</label>
                  <select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="w-full bg-muted border border-border rounded-md px-3 py-2 text-sm">
                    {["pending_approval", "queued", "applying", "applied", "viewed", "shortlisted", "interview_scheduled", "interview_completed", "offer_received", "offer_accepted", "offer_declined", "rejected", "withdrawn", "failed"].map(s => <option key={s} value={s}>{getStatusLabel(s)}</option>)}
                  </select>
                </div>
                {/* Specific fields based on status */}
                {form.status.includes("interview") && (
                  <div className="col-span-2 sm:col-span-1">
                    <label className="block text-xs text-muted-foreground mb-1">Interview Date</label>
                    <input type="datetime-local" value={form.interview_date} onChange={(e) => setForm({ ...form, interview_date: e.target.value })} className="w-full bg-muted border border-border rounded-md px-3 py-2 text-sm" />
                  </div>
                )}
                {form.status.includes("offer") && (
                  <div className="col-span-2 sm:col-span-1">
                    <label className="block text-xs text-muted-foreground mb-1">Offer Salary (₹)</label>
                    <input type="number" value={form.offer_salary} onChange={(e) => setForm({ ...form, offer_salary: e.target.value })} className="w-full bg-muted border border-border rounded-md px-3 py-2 text-sm" />
                  </div>
                )}
                <div className="col-span-2 sm:col-span-1">
                  <label className="block text-xs text-muted-foreground mb-1">Recruiter Name</label>
                  <input type="text" value={form.recruiter_name} onChange={(e) => setForm({ ...form, recruiter_name: e.target.value })} className="w-full bg-muted border border-border rounded-md px-3 py-2 text-sm" />
                </div>
                <div className="col-span-2 sm:col-span-1">
                  <label className="block text-xs text-muted-foreground mb-1">Recruiter Email</label>
                  <input type="email" value={form.recruiter_email} onChange={(e) => setForm({ ...form, recruiter_email: e.target.value })} className="w-full bg-muted border border-border rounded-md px-3 py-2 text-sm" />
                </div>
                <div className="col-span-2 border-t border-border/50 pt-4 mt-2">
                  <label className="block text-xs text-muted-foreground mb-1">Notes</label>
                  <textarea rows={4} value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} className="w-full bg-muted border border-border rounded-md px-3 py-2 text-sm resize-none" placeholder="Feedback, thoughts…" />
                </div>
              </div>
              <div className="flex justify-end gap-2 mt-4 pt-4 border-t border-border">
                <button type="button" onClick={() => setIsEditing(false)} className="px-4 py-2  rounded-md text-sm hover:bg-[#1c1c1e]">Cancel</button>
                <button type="submit" disabled={updateMut.isPending} className="px-4 py-2 bg-white text-black text-white rounded-md text-sm hover:bg-white text-black/90">Save Changes</button>
              </div>
            </form>
          ) : (
            <div className="-card p-6 space-y-6">
              {(app?.notes || app?.recruiter_name || app?.interview_date || app?.offer_salary) ? (
                <>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {app.recruiter_name && <div><p className="text-xs text-muted-foreground mb-1">Recruiter</p><p className="text-sm font-medium flex items-center gap-1.5"><Users className="w-3.5 h-3.5 text-muted-foreground" /> {app.recruiter_name}</p></div>}
                    {app.recruiter_email && <div><p className="text-xs text-muted-foreground mb-1">Email</p><p className="text-sm font-medium flex items-center gap-1.5"><Mail className="w-3.5 h-3.5 text-muted-foreground" /> {app.recruiter_email}</p></div>}
                    {app.interview_date && <div><p className="text-xs text-muted-foreground mb-1">Interview At</p><p className="text-sm font-medium flex items-center gap-1.5"><Calendar className="w-3.5 h-3.5 text-white-light" /> {formatDateTime(app.interview_date)}</p></div>}
                    {app.offer_salary && <div><p className="text-xs text-muted-foreground mb-1">Offer Salary</p><p className="text-sm font-medium text-brand-green">₹{app.offer_salary}</p></div>}
                  </div>
                  {app.notes && (
                    <div className="pt-4 border-t border-border">
                      <p className="text-xs text-muted-foreground flex items-center gap-1 mb-2"><AlignLeft className="w-3.5 h-3.5" /> Notes</p>
                      <p className="text-sm text-foreground/90 whitespace-pre-wrap">{app.notes}</p>
                    </div>
                  )}
                </>
              ) : (
                <div className="text-center py-6 text-muted-foreground"><p className="text-sm">No additional details added yet.</p><button onClick={handleEdit} className="text-white-light hover:underline text-sm mt-2">Add details</button></div>
              )}
            </div>
          )}

          {/* Connected Job/Resume */}
          <div className="-card p-6">
            <h3 className="font-semibold mb-4 text-sm">Linked Assets</h3>
            <div className="space-y-3 pt-2">
              <Link href={`/jobs/${app.job_id}`} className="flex items-center gap-3 p-3 bg-muted/30 rounded-lg hover:bg-muted/50 transition-colors">
                <Briefcase className="w-5 h-5 text-zinc-200 shrink-0" />
                <div className="flex-1"><p className="text-sm font-medium">Job Details</p><p className="text-xs text-muted-foreground">Original scraping and analysis</p></div>
                <ChevronRight className="w-4 h-4 text-muted-foreground" />
              </Link>
              {app.resume_id && (
                <Link href={`/resumes`} className="flex items-center gap-3 p-3 bg-muted/30 rounded-lg hover:bg-muted/50 transition-colors">
                  <FileText className="w-5 h-5 text-emerald-400 shrink-0" />
                  <div className="flex-1"><p className="text-sm font-medium">Applied Resume</p><p className="text-xs text-muted-foreground">View document used</p></div>
                  <ChevronRight className="w-4 h-4 text-muted-foreground" />
                </Link>
              )}
            </div>
          </div>
        </div>

        {/* Right Col - Timeline */}
        <div className="-card p-6">
          <h3 className="font-semibold mb-6 text-sm flex items-center gap-2"><Clock className="w-4 h-4" /> Lifecycle Timeline</h3>
          <div className="relative border-l border-border/80 ml-3 space-y-6">
            <div className="relative pl-6">
               <div className="absolute w-3 h-3 bg-card border-2 border-brand-primary rounded-full left-[-6.5px] top-1" />
               <p className="text-sm font-medium">{getStatusLabel(app.status)}</p>
               <p className="text-xs text-muted-foreground mt-0.5">Current Status</p>
            </div>
            {/* Real events would be mapped here (ApplicationEvent), stubbing common states for now */}
            {["applied_at", "viewed_at", "shortlisted_at", "offer_received_at", "rejected_at"].map(k => (
              app[k as keyof typeof app] && (
                <div key={k} className="relative pl-6 opacity-60">
                   <div className="absolute w-2 h-2 bg-muted-foreground rounded-full left-[-4px] top-1.5" />
                   <p className="text-sm">{k.replace("_at", "").replace("_", " ")}</p>
                   <p className="text-xs text-muted-foreground mt-0.5">{formatDate(app[k as keyof typeof app] as string)}</p>
                </div>
              )
            )).filter(Boolean).reverse()}
             <div className="relative pl-6 opacity-60">
               <div className="absolute w-2 h-2 bg-muted-foreground rounded-full left-[-4px] top-1.5" />
               <p className="text-sm">Created</p>
               <p className="text-xs text-muted-foreground mt-0.5">{formatDateTime(app.created_at)}</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { applicationsApi, agentApi } from "@/lib/api";
import { cn, getStatusClass, getStatusLabel, timeAgo, formatDate } from "@/lib/utils";
import Link from "next/link";
import { toast } from "sonner";
import { motion } from "framer-motion";
import { Search, Filter, LayoutGrid, List, SlidersHorizontal, Check, Star, RefreshCw, ChevronRight, AlertCircle, Play, Loader2, Layers } from "lucide-react";

const KANBAN_COLUMNS = [
  { id: "pending_approval", label: "Pending" },
  { id: "queued", label: "Queued" },
  { id: "applying", label: "Applying" },
  { id: "applied", label: "Applied" },
];

export default function ApplicationsPage() {
  const qc = useQueryClient();
  const [view, setView] = useState<"kanban" | "table">("kanban");
  const [filters, setFilters] = useState({ status: "", is_starred: undefined as boolean | undefined });
  const [page, setPage] = useState(1);
  const [isManualRefreshing, setIsManualRefreshing] = useState(false);

  const { data, isLoading, isRefetching, refetch } = useQuery({
    queryKey: ["applications", filters, page, view === "kanban" ? 100 : 20], // Load more for kanban
    queryFn: () => applicationsApi.list({ ...filters, page, page_size: view === "kanban" ? 100 : 20 }).then((r) => r.data),
  });

  const { data: stats } = useQuery({ queryKey: ["applications-stats"], queryFn: () => applicationsApi.stats().then((r) => r.data) });
  const { data: queue } = useQuery({ queryKey: ["queue-status"], queryFn: () => applicationsApi.queueStatus().then((r) => r.data) });

  const approveMut = useMutation({
    mutationFn: (id: string) => applicationsApi.approve(id),
    onSuccess: () => { toast.success("Approved! Sent to apply queue."); qc.invalidateQueries({ queryKey: ["applications"] }); qc.invalidateQueries({ queryKey: ["queue-status"] }); },
  });

  const starMut = useMutation({
    mutationFn: (id: string) => applicationsApi.star(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: ["applications"] }),
  });

  const triggerBot = useMutation({
    mutationFn: (id: string) => agentApi.applyOne(id),
    onSuccess: () => toast.success("Bot triggered manually! Check logs shortly."),
  });

  const isRefreshing = isManualRefreshing || isRefetching;

  const handleRefresh = async () => {
    if (isRefreshing) return;
    setIsManualRefreshing(true);
    try {
      await Promise.all([
        refetch(),
        qc.invalidateQueries({ queryKey: ["applications-stats"] }),
        qc.invalidateQueries({ queryKey: ["queue-status"] }),
      ]);
      toast.success("Applications data refreshed.");
    } finally {
      setIsManualRefreshing(false);
    }
  };

  // Group applications for Kanban
  const groupedApps = KANBAN_COLUMNS.reduce((acc, col) => {
    acc[col.id] = data?.items?.filter((app: any) => app.status === col.id) ?? [];
    return acc;
  }, {} as Record<string, any[]>);

  const pendingApps = data?.items?.filter((a: any) => a.status === "pending_approval") ?? [];

  return (
    <div className="dash-page space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3 justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-[#242424] border border-white/[0.08] rounded-lg">
            <Layers className="w-5 h-5 text-white" />
          </div>
          <div className="flex-1">
            <h1 className="text-2xl font-bold text-white">Applications Flow.</h1>
            <p className="text-sm text-zinc-400 mt-1">{data?.total ?? 0} total applications tracked across your automated career growth journey.</p>
            {isRefreshing && (
              <p className="mt-2 text-xs font-semibold text-zinc-300 flex items-center gap-2">
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
                Refreshing latest application activity...
              </p>
            )}
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button
            onClick={handleRefresh}
            disabled={isRefreshing}
            className="flex items-center gap-2 px-3 py-2 bg-[#1c1c1e] hover:bg-[#2a2a2a] text-white rounded-lg text-sm font-medium transition-colors border border-[#2a2a2a] disabled:opacity-60 disabled:cursor-not-allowed"
            title={isRefreshing ? "Refreshing..." : "Refresh"}
          >
            {isRefreshing ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4 text-zinc-300" />}
            <span>{isRefreshing ? "Refreshing..." : "Refresh"}</span>
          </button>
          <div className="flex p-1.5 bg-[#1c1c1e] rounded-2xl border border-[#262626]">
            <button 
              onClick={() => setView("kanban")} 
              aria-pressed={view === "kanban"}
              className={cn(
                "px-4 py-2 flex items-center gap-2 rounded-xl text-sm font-bold transition-all", 
                view === "kanban" ? "bg-[#2a2a2a] text-white" : "text-zinc-400 hover:text-zinc-300"
              )}
            >
              <LayoutGrid className="w-4 h-4" /> Kanban
            </button>
            <button 
              onClick={() => setView("table")} 
              aria-pressed={view === "table"}
              className={cn(
                "px-4 py-2 flex items-center gap-2 rounded-xl text-sm font-bold transition-all", 
                view === "table" ? "bg-[#2a2a2a] text-white" : "text-zinc-400 hover:text-zinc-300"
              )}
            >
              <List className="w-4 h-4" /> Table
            </button>
          </div>
        </div>
      </div>

      {pendingApps.length > 0 && filters.status === "" && (
        <div className="flex items-center gap-3 p-4 bg-amber-500/10 border border-amber-500/30 rounded-xl mb-2">
          <AlertCircle className="w-5 h-5 text-amber-400 shrink-0" />
          <div className="flex-1">
            <p className="text-sm font-medium text-amber-400">{pendingApps.length} applications pending approval</p>
          </div>
          <button onClick={() => pendingApps.forEach((a: any) => approveMut.mutate(a.id))}
            className="px-4 py-1.5 bg-white text-black rounded-lg text-xs font-medium hover:bg-zinc-200 transition-colors">
            Approve All
          </button>
        </div>
      )}

      {/* Main Content Area */}
      <div className="flex-1 min-h-0 overflow-hidden">
        {isLoading ? (
          <div className="flex h-full items-center justify-center py-20"><div className="w-12 h-12 rounded-full border-4 border-blue-500 border-t-transparent animate-spin" /></div>
        ) : view === "kanban" ? (
          <div className="h-full overflow-x-auto pb-8 -mx-2 px-2 scrollbar-none">
            <div className="flex gap-5 h-full min-w-max">
              {KANBAN_COLUMNS.map((col) => {
                const columnApps = groupedApps[col.id] || [];
                return (
                  <div key={col.id} className="w-80 flex flex-col bg-[#242424] border border-white/[0.08] rounded-2xl p-4 max-h-[70vh] shadow-[inset_0_1px_0_rgba(255,255,255,0.035)]">
                    <div className="px-4 py-3 mb-4 flex items-center justify-between shrink-0">
                      <span className="font-bold text-[11px] tracking-[0.2em] text-zinc-300 uppercase">{col.label}</span>
                      <span className="text-[10px] font-black px-2.5 py-1 bg-[#1c1c1c] border border-white/[0.08] rounded-full text-zinc-300">{columnApps.length}</span>
                    </div>
                    <div className="flex-1 overflow-y-auto space-y-3 px-1 pb-4 scrollbar-none">
                      {columnApps.map((app) => (
                        <motion.div 
                          key={app.id} 
                          whileHover={{ y: -3 }}
                          className="bg-[#1d1d1d] p-5 rounded-2xl border border-white/[0.08] hover:border-white/20 relative group transition-all shadow-[inset_0_1px_0_rgba(255,255,255,0.02)]"
                        >
                          <button onClick={(e) => { e.stopPropagation(); starMut.mutate(app.id); }} className="absolute top-4 right-4 text-zinc-400 hover:text-amber-400 transition-colors z-10 w-8 h-8 flex items-center justify-center">
                            <Star className={cn("w-4 h-4", app.is_starred ? "fill-amber-400 text-amber-400" : "")} />
                          </button>
                          <div className={cn("inline-block px-3 py-1 text-[9px] font-black uppercase tracking-widest rounded-full mb-3 border", getStatusClass(col.id))}>{getStatusLabel(col.id)}</div>
                          <p className="font-black text-sm text-white leading-tight pr-6 tracking-tight mb-1">{app.job_title_snapshot}</p>
                          <p className="text-zinc-400 text-xs font-medium">{app.company_snapshot}</p>

                          <div className="flex items-center justify-between mt-4 text-[10px] font-bold text-zinc-400 uppercase tracking-widest">
                            <span>{timeAgo(app.created_at)}</span>
                            {app.match_score_at_apply && <span className="text-zinc-200 bg-white/10 border border-white/20 px-2 py-0.5 rounded-full">{Math.round(app.match_score_at_apply)}%</span>}
                          </div>

                          {col.id === "pending_approval" && (
                            <div className="mt-4 pt-3 border-t border-white/10 flex gap-2">
                              <button onClick={(e) => { e.stopPropagation(); approveMut.mutate(app.id); }} className="flex-1 px-4 py-2 bg-white text-black text-[10px] font-black uppercase tracking-widest rounded-xl hover:bg-zinc-200 transition-colors">Approve</button>
                            </div>
                          )}
                          {col.id === "queued" && (
                            <div className="mt-4 pt-3 border-t border-white/[0.08]">
                              <button onClick={(e) => { e.stopPropagation(); triggerBot.mutate(app.id); }} className="w-full px-4 py-2 flex items-center justify-center gap-2 bg-[#252525] text-zinc-300 text-[10px] font-black uppercase tracking-widest rounded-xl hover:bg-[#303030] transition-colors border border-white/[0.08]">
                                <Play className="w-3 h-3" /> Force Deploy
                              </button>
                            </div>
                          )}
                        </motion.div>
                      ))}
                      {columnApps.length === 0 && (
                        <div className="h-24 flex items-center justify-center bg-[#1d1d1d] border border-white/[0.08] rounded-2xl shadow-[inset_0_1px_0_rgba(255,255,255,0.02)]">
                          <p className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.3em] italic">Empty Sector</p>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ) : (
          <div className="bg-[#242424] border border-white/[0.08] rounded-xl overflow-hidden h-full flex flex-col shadow-[inset_0_1px_0_rgba(255,255,255,0.035)]">
            <div className="overflow-x-auto flex-1">
              <table className="w-full text-sm text-left whitespace-nowrap">
                <thead className="bg-[#1d1d1d] text-zinc-400 border-b border-white/[0.08] sticky top-0 z-10">
                  <tr>
                    <th className="px-4 py-3 font-medium cursor-pointer w-10">⭐</th>
                    <th className="px-4 py-3 font-medium">Role & Company</th>
                    <th className="px-4 py-3 font-medium">Status</th>
                    <th className="px-4 py-3 font-medium">Match</th>
                    <th className="px-4 py-3 font-medium">Date</th>
                    <th className="px-4 py-3 font-medium">Recruiter</th>
                    <th className="px-4 py-3 font-medium text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {data?.items?.map((app: any) => (
                    <tr key={app.id} className="hover:bg-white/[0.02] transition-colors group">
                      <td className="px-4 py-3">
                        <button onClick={() => starMut.mutate(app.id)} className="text-muted-foreground hover:text-amber-400">
                          <Star className={cn("w-4 h-4", app.is_starred ? "fill-amber-400 text-amber-400" : "")} />
                        </button>
                      </td>
                      <td className="px-4 py-3">
                        <p className="font-semibold">{app.job_title_snapshot}</p>
                        <p className="text-xs text-muted-foreground">{app.company_snapshot}</p>
                      </td>
                      <td className="px-4 py-3">
                        <span className={cn("px-2 py-1 text-[10px] font-bold rounded border", getStatusClass(app.status))}>{getStatusLabel(app.status)}</span>
                      </td>
                      <td className="px-4 py-3 font-medium">{app.match_score_at_apply ? `${Math.round(app.match_score_at_apply)}%` : "—"}</td>
                      <td className="px-4 py-3 text-muted-foreground text-xs">{formatDate(app.created_at)}</td>
                      <td className="px-4 py-3 text-xs">{app.recruiter_name ?? "—"}</td>
                      <td className="px-4 py-3 text-right">
                        {app.status === "pending_approval" ? (
                          <button onClick={() => approveMut.mutate(app.id)} className="px-3 py-1 bg-white text-black text-white text-xs font-medium rounded hover:bg-white text-black/90">Approve</button>
                        ) : (
                          <Link href={`/applications/${app.id}`} className="text-white-light hover:underline text-xs inline-flex items-center gap-1">View <ChevronRight className="w-3 h-3" /></Link>
                        )}
                      </td>
                    </tr>
                  ))}
                  {data?.items?.length === 0 && <tr><td colSpan={7} className="px-4 py-8 text-center text-muted-foreground">No applications found.</td></tr>}
                </tbody>
              </table>
            </div>
            {data && data.pages > 1 && (
              <div className="p-3 border-t border-white/[0.08] flex items-center justify-center gap-2 shrink-0 bg-[#1d1d1d]">
                <button onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={page === 1} className="px-3 py-1 bg-[#252525] border border-white/[0.08] text-white rounded text-xs disabled:opacity-50 disabled:cursor-not-allowed">Prev</button>
                <span className="text-xs text-zinc-500">Page {page} of {data.pages}</span>
                <button onClick={() => setPage((p) => Math.min(data.pages, p + 1))} disabled={page === data.pages} className="px-3 py-1 bg-[#252525] border border-white/[0.08] text-white rounded text-xs disabled:opacity-50 disabled:cursor-not-allowed">Next</button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";
import { useState, useRef, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { chatApi } from "@/lib/api";
import { motion, AnimatePresence } from "framer-motion";
import { Send, Bot, BotMessageSquare, User as UserIcon, Brain, Zap, Trash2, Sparkles, Target, Search, FileText, Mail, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

interface Message {
  role: "user" | "assistant";
  content: string;
  timestamp?: Date;
}

const personas = [
  { id: "general", label: "General", icon: Sparkles, color: "text-white" },
  { id: "career_coach", label: "Career Coach", icon: Target, color: "text-white" },
  { id: "resume_expert", label: "Resume Expert", icon: FileText, color: "text-white" },
  { id: "job_scout", label: "Job Scout", icon: Search, color: "text-white" },
  { id: "application_assistant", label: "Apply Helper", icon: Mail, color: "text-white" },
];

function TypingIndicator() {
  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="flex items-center gap-1 px-4 py-3 bg-white/10 rounded-2xl rounded-bl-md"
    >
      {[0, 1, 2].map((i) => (
        <motion.div
          key={i}
          className="w-2 h-2 bg-white text-black border border-zinc-800/60 rounded-full"
          animate={{ y: [0, -4, 0], opacity: [0.5, 1, 0.5] }}
          transition={{
            duration: 0.6,
            repeat: Infinity,
            delay: i * 0.15,
          }}
        />
      ))}
    </motion.div>
  );
}

export default function ChatPage() {
  const [messages, setMessages] = useState<Message[]>([
    { role: "assistant", content: "Hi! I'm Lumi, your personal career assistant. Need help? Call 📞 9751120169 (Mon-Sat, 9AM-6PM) or email applivoagent@gmail.com. I can help with resume tailoring, job searches, interview prep, and more!", timestamp: new Date() }
  ]);
  const [input, setInput] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [persona, setPersona] = useState("general");
  const endRef = useRef<HTMLDivElement>(null);

  const queryClient = useQueryClient();

  const { data: credits } = useQuery({
    queryKey: ["chat-credits"],
    queryFn: () => chatApi.credits().then((r) => r.data),
  });

  const { data: history, isLoading: historyLoading } = useQuery({
    queryKey: ["chat-history"],
    queryFn: () => chatApi.history(50).then((r) => r.data),
  });

  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => {
    if (history && history.length > 0) {
      const loadedMessages: Message[] = history.reverse().map((m: { role: string; content: string; created_at?: string }) => ({
        role: m.role as "user" | "assistant",
        content: m.content,
        timestamp: m.created_at ? new Date(m.created_at) : new Date(),
      }));
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setMessages([
        { role: "assistant", content: "Hi! I'm Lumi, your personal career assistant. Need help? Call 📞 9751120169 (Mon-Sat, 9AM-6PM) or email support@applivo.com. I can help with resume tailoring, job searches, interview prep, and more!", timestamp: new Date() },
        ...loadedMessages,
      ]);
    }
  }, [history]);

  const clearHistoryMut = useMutation({
    mutationFn: () => chatApi.clearHistory(),
    onSuccess: () => {
      setMessages([
        { role: "assistant", content: "Hi! I'm Lumi, your personal career assistant. Need help? Call 📞 9751120169 (Mon-Sat, 9AM-6PM) or email support@applivo.com. I can help with resume tailoring, job searches, interview prep, and more!", timestamp: new Date() }
      ]);
      queryClient.invalidateQueries({ queryKey: ["chat-history"] });
    },
  });

  const chatMut = useMutation({
    mutationFn: (msg: string) => chatApi.send({
      message: msg,
      history: messages.map(m => ({ role: m.role, content: m.content })),
      persona,
    }),
    onMutate: (msg) => {
      setMessages(prev => [...prev, { role: "user", content: msg, timestamp: new Date() }, { role: "assistant", content: "...", timestamp: new Date() }]);
      setInput("");
      setIsTyping(true);
    },
    onSuccess: (res) => {
      setIsTyping(false);
      setMessages(prev => {
        const newMsgs = [...prev];
        newMsgs[newMsgs.length - 1] = { role: "assistant", content: res.data.response, timestamp: new Date() };
        return newMsgs;
      });
    },
    onError: () => {
      setIsTyping(false);
      setMessages(prev => {
        const newMsgs = [...prev];
        newMsgs[newMsgs.length - 1] = { role: "assistant", content: "Sorry, I ran into an error processing that request.", timestamp: new Date() };
        return newMsgs;
      });
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["chat-credits"] });
    }
  });

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || chatMut.isPending) return;
    chatMut.mutate(input);
  };

  const getCreditDisplay = () => {
    if (!credits) return null;
    if (credits.is_unlimited) {
      return { label: "Unlimited", color: "text-white" };
    }
    if (credits.remaining <= 10) {
      return { label: `${credits.remaining} credits`, color: "text-zinc-400" };
    }
    return { label: `${credits.remaining} credits`, color: "text-white" };
  };

  const creditDisplay = getCreditDisplay();

  return (
    <div className="flex flex-col h-[calc(100vh-4.5rem)] relative">
      {/* Header */}
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex items-center justify-between pb-4 border-b border-white/10 shrink-0"
      >
        <div className="flex items-center gap-4">
          <motion.div
            whileHover={{ scale: 1.1 }}
            className="w-12 h-12 rounded-2xl bg-[#1c1c1e] text-white border border-zinc-800 flex items-center justify-center shadow-lg shadow-white/5"
          >
            <BotMessageSquare className="w-6 h-6 text-white" />
          </motion.div>
          <div>
            <h1 className="text-xl font-bold text-white leading-tight">Lumi</h1>
            <div className="flex items-center gap-2 mt-0.5">
              <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse" />
              <p className="text-xs text-zinc-400 font-medium">Powered by LLaMA-3.1-8B</p>
            </div>
          </div>
        </div>

        {/* Persona Picker */}
        <div className="flex items-center gap-1.5 bg-white/10 p-1 rounded-xl">
          {personas.map((p) => {
            const Icon = p.icon;
            const isActive = persona === p.id;
            return (
              <button
                key={p.id}
                onClick={() => setPersona(p.id)}
                className={cn(
                  "flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-all",
                  isActive
                    ? "bg-[#1c1c1e] shadow-sm text-white border border-zinc-800"
                    : "text-zinc-400 hover:text-zinc-300"
                )}
                title={p.label}
              >
                <Icon className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">{p.label}</span>
              </button>
            );
          })}
        </div>

        {/* Credits Display */}
        {creditDisplay && (
          <div className="flex items-center gap-3">
            <button
              onClick={() => clearHistoryMut.mutate()}
              disabled={clearHistoryMut.isPending}
              className="p-2.5 rounded-xl hover:bg-[#1c1c1e]/10 text-zinc-400 hover:text-zinc-400 transition-colors"
              title="Clear chat history"
            >
              <Trash2 className="w-4 h-4" />
            </button>
            <motion.div
              whileHover={{ scale: 1.05 }}
              className={cn("flex items-center gap-2 px-4 py-2 rounded-full bg-white/5 border border-white/10", creditDisplay.color)}
            >
              <Zap className="w-4 h-4" />
              <span className="text-sm font-semibold">{creditDisplay.label}</span>
            </motion.div>
          </div>
        )}
      </motion.div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto py-6 px-4 space-y-6 scrollbar-hide">
        <AnimatePresence initial={false}>
          {messages.map((m, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 10, scale: 0.98 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              transition={{ duration: 0.3 }}
              className={cn("flex gap-4 max-w-3xl", m.role === "user" ? "ml-auto flex-row-reverse" : "")}
            >
              <motion.div
                whileHover={{ scale: 1.05 }}
                className={cn("w-9 h-9 rounded-xl flex items-center justify-center shrink-0 mt-1",
                  m.role === "user"
                    ? "bg-white text-black border border-zinc-800"
                    : "bg-[#1c1c1e] text-white border border-zinc-800 shadow-sm")}
              >
                {m.role === "user" ? <UserIcon className="w-4 h-4" /> : <BotMessageSquare className="w-4 h-4" />}
              </motion.div>
              <div className={cn("px-5 py-4 rounded-2xl text-sm leading-relaxed whitespace-pre-wrap shadow-sm max-w-[80%]",
                m.role === "user"
                  ? "bg-[#2a2a2a] text-white rounded-tr-none border border-zinc-700"
                  : "bg-[#1c1c1e] border border-white/10 text-zinc-300 rounded-tl-none")}>
                {m.content === "..." ? <TypingIndicator /> : m.content}
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
        <div ref={endRef} />
      </div>

      {/* Input */}
      <div className="pt-4 pb-0 border-t border-white/10 shrink-0 bg-[#050505] backdrop-blur">
        <form onSubmit={handleSubmit} className="relative">
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSubmit(e);
              }
            }}
            placeholder="Ask about interviewing, resume tailoring, or job matching..."
            className="w-full bg-white/5 border border-white/10 rounded-2xl pl-5 pr-14 py-4 text-sm focus:outline-none focus:ring-2 focus:ring-brand-primary/30 focus:bg-[#1c1c1e] resize-none h-[72px] transition-all"
            rows={1}
          />
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            type="submit"
            disabled={!input.trim() || chatMut.isPending}
            className="absolute right-3 top-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center bg-white text-black border border-zinc-800 text-black rounded-xl hover:shadow-lg hover:shadow-brand-primary/30 disabled:opacity-80 disabled:cursor-not-allowed disabled:bg-zinc-200 transition-all"
          >
            {chatMut.isPending ? (
              <motion.div
                className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full"
                animate={{ rotate: 360 }}
                transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
              />
            ) : (
              <Send className="w-4 h-4 text-black" />
            )}
          </motion.button>
        </form>
        <p className="text-center text-[10px] text-zinc-400 mt-2">Assistant uses your profile data and applications context to generate answers.</p>
      </div>
    </div>
  );
}

"use client";
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { platformApi } from "@/lib/api";
import { toast } from "sonner";
import { Link2, Trash2, Plus, Shield, Globe, Lock, CheckCircle, XCircle, Key, Cookie, Loader2, Eye, EyeOff } from "lucide-react";
import { cn } from "@/lib/utils";

type ConnectionMode = "login" | "cookies";

export default function ConnectPage() {
  const qc = useQueryClient();
  const [platform, setPlatform] = useState("internshala");
  const [mode, setMode] = useState<ConnectionMode>("login");
  const [cookieString, setCookieString] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);

  const { data: status, isLoading } = useQuery({
    queryKey: ["platform-status"],
    queryFn: () => platformApi.status().then((r) => r.data),
  });

  const hasInternshalaConnection = (status?.platforms || []).some(
    (p: any) => p.platform === "internshala"
  );

  const connectMut = useMutation({
    mutationFn: () => platformApi.connect({ 
      platform, 
      cookies: cookieString 
    }),
    onSuccess: () => { 
      toast.success("Platform connected & cookies encrypted"); 
      setCookieString(""); 
      qc.invalidateQueries({ queryKey: ["platform-status"] }); 
    },
    onError: (err: any) => toast.error(err?.response?.data?.detail || "Failed to connect platform"),
  });

  const loginMut = useMutation({
    mutationFn: () => platformApi.login(platform, { email, password }),
    onSuccess: (res) => { 
      toast.success("Successfully logged into " + platform);
      setEmail("");
      setPassword("");
      qc.invalidateQueries({ queryKey: ["platform-status"] });
    },
    onError: (err: any) => toast.error(err?.response?.data?.detail || "Login failed - check credentials or try again"),
  });

  const invalidateMut = useMutation({
    mutationFn: (p: string) => platformApi.disconnect(p),
    onSuccess: () => { 
      toast.success("Platform disconnected"); 
      qc.invalidateQueries({ queryKey: ["platform-status"] }); 
    },
    onError: () => toast.error("Failed to disconnect"),
  });

  const handleCookiesSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!cookieString) return;
    connectMut.mutate();
  };

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) return;
    loginMut.mutate();
  };

  const platforms = status?.platforms || [];

  return (
    <div className="max-w-4xl space-y-8">
      <div className="flex items-center gap-3">
        <div className="p-2 bg-[#242424] border border-white/[0.08] rounded-lg">
          <Link2 className="w-5 h-5 text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-bold text-white">Connect Platforms</h1>
          <p className="text-sm text-zinc-400 mt-1">Connect your job board accounts to enable automated applications.</p>
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-6">
        {/* Connection Form */}
        <div className="bg-[#242424] border border-white/[0.08] rounded-2xl shadow-[inset_0_1px_0_rgba(255,255,255,0.035)] p-6">
          <h2 className="text-[12px] font-medium uppercase tracking-[0.2em] text-gray-400 mb-4 flex items-center gap-2">
            <Link2 className="w-5 h-5 text-white" /> 
            Connect {platform.charAt(0).toUpperCase() + platform.slice(1)}
          </h2>

          {hasInternshalaConnection && (
            <div className="mb-4 p-3 bg-amber-500/10 border border-amber-500/30 rounded-lg text-[12px] text-amber-300">
              Internshala is already connected. Delete the existing connection from Active Sessions before connecting another account.
            </div>
          )}

          <div className="flex gap-2 mb-4">
            <button
              type="button"
              onClick={() => setMode("login")}
              disabled={hasInternshalaConnection}
              className={`flex-1 py-2 px-3 text-[11px] font-medium rounded-lg flex items-center justify-center gap-2 transition-all ${
                mode === "login" 
                  ? "bg-white text-black" 
                  : "bg-[#1d1d1d] border border-[#34343a] text-[#A1A1AA] hover:bg-[#1d1d1d]"
              } ${hasInternshalaConnection ? "opacity-50 cursor-not-allowed" : ""}`}
            >
              <Key className="w-3 h-3" /> Login with Email
            </button>
            <button
              type="button"
              onClick={() => setMode("cookies")}
              disabled={hasInternshalaConnection}
              className={`flex-1 py-2 px-3 text-[11px] font-medium rounded-lg flex items-center justify-center gap-2 transition-all ${
                mode === "cookies" 
                  ? "bg-white text-black" 
                  : "bg-[#1d1d1d] border border-[#34343a] text-[#A1A1AA] hover:bg-[#1d1d1d]"
              } ${hasInternshalaConnection ? "opacity-50 cursor-not-allowed" : ""}`}
            >
              <Cookie className="w-3 h-3" /> Paste Cookies
            </button>
          </div>

          {mode === "login" ? (
            <form onSubmit={handleLoginSubmit} className="space-y-4">
              <div>
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-gray-500 mb-1">Email</label>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="your@email.com"
                  className="w-full bg-[#1d1d1d] border border-[#34343a] rounded-lg px-3 py-2.5 text-[13px] text-white placeholder-[#A1A1AA] focus:border-white/30 transition-all outline-none"
                />
              </div>
              <div>
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-gray-500 mb-1">Password</label>
                <div className="relative">
                  <input
                    type={showPassword ? "text" : "password"}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Your Internshala password"
                    className="w-full bg-[#1d1d1d] border border-[#34343a] rounded-lg px-3 py-2.5 pr-10 text-[13px] text-white placeholder-[#A1A1AA] focus:border-white/30 transition-all outline-none"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-[#A1A1AA] hover:text-white transition-colors"
                  >
                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              <div className="p-3 bg-[#1d1d1d] border border-[#34343a] rounded-lg flex gap-3 text-[11px] text-[#A1A1AA]">
                <Shield className="w-4 h-4 shrink-0 mt-0.5 text-white" />
                <p>Your credentials are never stored. We use them only to obtain a session and then save encrypted cookies.</p>
              </div>

              <button 
                type="submit" 
                disabled={loginMut.isPending || hasInternshalaConnection} 
                className="w-full py-2.5 bg-white text-black rounded-lg text-[13px] font-semibold hover:bg-gray-200 transition-all disabled:opacity-80 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                <Globe className="w-4 h-4" /> 
                {loginMut.isPending ? "Logging in..." : "Login to " + platform}
              </button>

              {loginMut.isPending && (
                <p className="text-[11px] text-center text-[#A1A1AA]">
                  A browser window opened. Log in to Internshala manually, then wait for success.
                </p>
              )}
            </form>
          ) : (
            <form onSubmit={handleCookiesSubmit} className="space-y-4">
              <div>
                <label className="block text-[10px] font-bold uppercase tracking-[0.2em] text-gray-500 mb-1">Raw Cookie String</label>
                <textarea
                  value={cookieString}
                  onChange={(e) => setCookieString(e.target.value)}
                  placeholder="Paste your document.cookie string here..."
                  rows={4}
                  className="w-full bg-[#1d1d1d] border border-[#34343a] rounded-lg px-3 py-2.5 text-[13px] font-mono text-white placeholder-[#A1A1AA] resize-none focus:border-white/30 transition-all outline-none"
                />
                <p className="text-[11px] text-[#A1A1AA] mt-1">
                  Log into {platform}, open DevTools → Console, type <code className="bg-[#232327] px-1 py-0.5 rounded text-white border border-white/10">document.cookie</code> and paste.
                </p>
              </div>

              <div className="p-3 bg-[#232327] border border-[#34343a] rounded-lg flex gap-3 text-xs text-[#A1A1AA]">
                <Shield className="w-4 h-4 shrink-0 mt-0.5 text-white" />
                <p>Your cookies are encrypted in our database using AES-256 and only decrypted in memory when the automation runs.</p>
              </div>

              <button 
                type="submit" 
                disabled={!cookieString || connectMut.isPending || hasInternshalaConnection} 
                className="w-full py-2.5 bg-white text-black rounded-lg text-[13px] font-semibold hover:bg-gray-200 transition-all disabled:opacity-80 disabled:cursor-not-allowed flex items-center justify-center gap-2"
              >
                <Plus className="w-4 h-4" /> 
                {connectMut.isPending ? "Connecting..." : "Connect Platform"}
              </button>
            </form>
          )}
        </div>

        {/* Existing Connections */}
        <div className="bg-[#242424] border border-white/[0.08] rounded-2xl shadow-[inset_0_1px_0_rgba(255,255,255,0.035)] p-6">
          <h2 className="text-[12px] font-medium uppercase tracking-[0.2em] text-gray-400 mb-4">Active Sessions</h2>

          {isLoading ? (
            <div className="space-y-3">{[1,2].map(i => <div key={i} className="h-20 bg-[#1d1d1d] border border-white/[0.06] animate-pulse rounded-xl" />)}</div>
          ) : platforms.length > 0 ? (
            <div className="space-y-3">
              {platforms.map((p: any) => (
                <div key={p.platform} className="p-4 bg-[#1d1d1d] border border-[#34343a] rounded-xl flex items-center justify-between group">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg bg-[#1d1d1d] flex flex-col items-center justify-center border border-[#34343a]">
                      <Globe className="w-4 h-4 text-white" />
                    </div>
                    <div>
                      <p className="font-semibold text-white text-[13px] capitalize flex items-center gap-2">
                        {p.platform} 
                        {p.is_valid ? (
                          <CheckCircle className="w-3 h-3 text-emerald-400" />
                        ) : (
                          <XCircle className="w-3 h-3 text-red-400" />
                        )}
                      </p>
