"use client";
import React, { useEffect, useState } from "react";
import { Mail, RefreshCw, Loader2, Star, AlertTriangle } from "lucide-react";
import { platformApi } from "@/lib/api";
import { toast } from "sonner";

interface PlatformMessage {
  id: string;
  sender: string;
  subject: string;
  content: string;
  is_important: boolean;
  importance_keywords: string | null;
  received_at: string | null;
  platform: string;
}

export default function MessagesPage() {
  const [messages, setMessages] = useState<PlatformMessage[]>([]);
  const [loading, setLoading] = useState(true);
  const [scanning, setScanning] = useState(false);
  const [filter, setFilter] = useState<"all" | "important" | "urgent">("all");

  useEffect(() => { loadMessages(); }, []);

  const loadMessages = async () => {
    setLoading(true);
    try {
      const res = await platformApi.messages("internshala", 50);
      setMessages(res.data);
    } catch (err: any) {
      toast.error(err?.response?.data?.detail || "Failed to load messages");
    } finally {
      setLoading(false);
    }
  };

  const handleScan = async () => {
    setScanning(true); setLoading(true);
    try {
      await platformApi.scanMessages("internshala");
      toast.success("Sync completed");
      loadMessages();
    } catch (err: any) {
      toast.error(err?.response?.data?.detail || "Sync failed");
    } finally {
      setScanning(false);
    }
  };

  const filteredMessages = messages.filter((msg) => {
    if (filter === "important") return msg.is_important;
    if (filter === "urgent") {
      const c = msg.content.toLowerCase();
      return c.includes("deadline") || c.includes("expires") || c.includes("urgent");
    }
    return true;
  });

  const importantCount = messages.filter(m => m.is_important).length;
  const urgentCount = messages.filter(m => {
    const c = m.content.toLowerCase();
    return c.includes("deadline") || c.includes("expires") || c.includes("urgent");
  }).length;

  const formatMessage = (content: string, sender: string) => {
    const lines = content.split('\n').map(l => l.trim()).filter(l => l);

    let company = sender && sender !== "Internshala Chat" ? sender : "";
    let jobTitle = "";
    let time = "";
    let date = "";
    let isUrgent = false;

    // If company not from sender, try to extract from content
    if (!company) {
      // Look for pattern like "Company | Chatting with..."
      for (const line of lines) {
        if (line.includes('|') && line.includes('Chatting')) {
          company = line.split('|')[0].trim();
          break;
        }
      }
      // Or first line that's not "Internshala Chat" or "You:"
      if (!company) {
        for (const line of lines) {
          if (line && !line.includes('Chat') && !line.startsWith('You:') && line.length > 2 && line.length < 40) {
            company = line;
            break;
          }
        }
      }
    }

    // Find job title - look for "internship" in any line
    for (const line of lines) {
      if (line.toLowerCase().includes('internship')) {
        jobTitle = line.replace(/internship/gi, '').trim();
        break;
      }
    }

    // Find time
    for (const line of lines) {
      const timeMatch = line.match(/^(\d{1,2}:\d{2}\s*(?:AM|PM)?)/i);
      if (timeMatch) {
        time = timeMatch[1];
        break;
      }
    }

    // Find date
    for (const line of lines) {
      const dateMatch = line.match(/^(\d{2}\/\d{2}\/\d{4})/);
      if (dateMatch) {
        date = dateMatch[1];
        break;
      }
    }

    // Check urgent
    if (content.toLowerCase().includes('deadline') || content.toLowerCase().includes('expires')) {
      isUrgent = true;
    }

    return { company, jobTitle, time, date, isUrgent };
  };

  const [selectedMessage, setSelectedMessage] = useState<PlatformMessage | null>(null);

  return (
    <div className="dash-page p-6 max-w-5xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-[#242424] border border-white/[0.08] rounded-lg">
            <Mail className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-white">Platform Messages</h1>
            <p className="text-sm text-zinc-400 mt-1">Real-time updates from Internshala recruiter chats and invites.</p>
          </div>
        </div>
        <button
          onClick={handleScan}
          disabled={scanning}
          className="flex items-center gap-2 px-4 py-2 bg-white text-black hover:bg-gray-200 rounded-lg disabled:opacity-80 disabled:cursor-not-allowed transition-all text-sm font-medium shadow-lg"
        >
          {scanning ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
          {scanning ? "Syncing Inbox..." : "Sync Messages"}
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-3">
        <div className="dash-stat-card bg-[#242424] border-white/[0.08] shadow-[inset_0_1px_0_rgba(255,255,255,0.035)]">
          <div className="dash-value">{messages.length}</div>
          <div className="dash-label mt-1">Total Messages</div>
        </div>
        <div className="dash-stat-card bg-[#242424] border-white/[0.08] shadow-[inset_0_1px_0_rgba(255,255,255,0.035)]">
          <div className="dash-value">{importantCount}</div>
          <div className="dash-label mt-1">Important</div>
        </div>
        <div className="dash-stat-card bg-[#242424] border-white/[0.08] shadow-[inset_0_1px_0_rgba(255,255,255,0.035)]">
          <div className="dash-value">{urgentCount}</div>
          <div className="dash-label mt-1">Urgent Action</div>
        </div>
      </div>

      {/* Filters */}
      <div className="flex gap-2">
        <button onClick={() => setFilter("all")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${filter === "all" ? "bg-white text-black shadow-lg" : " hover:bg-white/5 text-zinc-400"}`}>
          All ({messages.length})
        </button>
        <button onClick={() => setFilter("important")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${filter === "important" ? "bg-white text-black shadow-lg" : " hover:bg-white/5 text-zinc-400"}`}>
          Important ({importantCount})
        </button>
        <button onClick={() => setFilter("urgent")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${filter === "urgent" ? "bg-white text-black shadow-lg" : " hover:bg-white/5 text-zinc-400"}`}>
          Urgent ({urgentCount})
        </button>
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 gap-3">
          <Loader2 className="w-10 h-10 animate-spin text-white" />
          <p className="text-sm text-muted-foreground animate-pulse">Scanning platform inboxes...</p>
        </div>
      ) : filteredMessages.length === 0 ? (
        <div className="text-center py-20 bg-[#242424] border border-white/[0.08] rounded-[20px] shadow-[inset_0_1px_0_rgba(255,255,255,0.035)] transition-all">
          <div className="w-12 h-12 rounded-full bg-[#1d1d1d] border border-white/[0.08] flex items-center justify-center mx-auto mb-6">
            <Mail className="w-5 h-5 text-zinc-600" />
          </div>
          <p className="text-[11px] font-black uppercase tracking-[0.2em] text-zinc-500 mb-2">Inbox Deployed / No outreach detected</p>
          <p className="text-[10px] font-bold text-zinc-700 max-w-[200px] mx-auto uppercase tracking-wider leading-relaxed italic">
            Sync your platform credentials to scan for hidden recruiter callbacks.
          </p>
        </div>
      ) : (
        <div className="grid gap-3">
          {filteredMessages.map((msg) => {
            const isUrgent = msg.content.toLowerCase().includes('deadline') || msg.content.toLowerCase().includes('expires');
            const receivedDate = msg.received_at ? new Date(msg.received_at) : null;
            const timeStr = receivedDate ? receivedDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : "";
            const dateStr = receivedDate ? receivedDate.toLocaleDateString([], { month: 'short', day: 'numeric' }) : "Recently";

            let displaySender = msg.sender;
            if (displaySender && displaySender.includes('. Accept')) displaySender = displaySender.split('. Accept')[0];
            if (displaySender && displaySender.includes('. Get')) displaySender = displaySender.split('. Get')[0];

            if (!displaySender || displaySender === "Internshala Chat" || displaySender === "Unknown") {
                const pat = /(?:internship|role|position|opportunity) at ([A-Z][A-Za-z0-9 &]+?)(?:\.|,|\n| Accept| Get| Please| We| I| This)/i;
                const match = msg.content.match(pat);
                if (match && match[1]) {
                    displaySender = match[1].trim();
                }
            }
            if (!displaySender || displaySender === "Internshala Chat" || displaySender === "Unknown") {
                const pat = /(?:message from|team from|on behalf of) ([A-Z][A-Za-z0-9 &]+?)(?:\.|,|\n| Accept| Get| Please)/i;
                const match = msg.content.match(pat);
                if (match && match[1]) displaySender = match[1].trim();
            }
            if (!displaySender || displaySender === "Internshala Chat" || displaySender === "Unknown") {
                const pat = /(?:We are interested in your profile for.*?at )([A-Z][A-Za-z0-9 &]+)/i;
                const match = msg.content.match(pat);
                if (match && match[1]) displaySender = match[1].trim();
            }

            return (
              <div
                key={msg.id}
                onClick={() => setSelectedMessage(msg)}
                className={`p-5 rounded-2xl bg-[#242424] border border-white/[0.08] cursor-pointer hover:border-white/20 transition-all shadow-[inset_0_1px_0_rgba(255,255,255,0.035)] group`}
              >
                <div className="flex items-center justify-between mb-1">
                    <div className="flex items-center gap-2">
                      {msg.is_important && <Star className="w-4 h-4 text-white fill-white" />}
                      {isUrgent && <AlertTriangle className="w-4 h-4 text-white" />}
                      <span className="font-bold text-lg group-hover:text-white transition-colors">{displaySender}</span>
                    </div>
                  <div className="text-[9px] text-muted-foreground uppercase tracking-[0.2em] font-bold bg-white/5 px-2 py-1 rounded">
                    {msg.platform}
                  </div>
                </div>

                <div className="text-white font-semibold text-sm mb-3 ml-0">
                  {msg.subject || "Platform Notification"}
                </div>

                <div className="flex items-end justify-between gap-6">
                  <div className="text-sm text-white/50 line-clamp-2 leading-relaxed flex-1 italic">
                    "{msg.content}"
                  </div>
                  <div className="text-[11px] text-zinc-500 whitespace-nowrap text-right font-medium">
                    <div className="text-white/80">{timeStr}</div>
                    <div className="opacity-60">{dateStr}</div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Message Detail Modal */}
      {selectedMessage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[#111118]/90 backdrop-blur-sm animate-in fade-in duration-200" onClick={() => setSelectedMessage(null)}>
          <div className="bg-[#242424] w-full max-w-2xl max-h-[80vh] overflow-hidden flex flex-col border border-white/[0.08] rounded-2xl shadow-2xl animate-in zoom-in-95 duration-200" onClick={e => e.stopPropagation()}>
            <div className="p-6 border-b border-white/[0.08] bg-[#232327]">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-2xl font-bold text-white">
                      {selectedMessage.sender.includes('. Accept') ? selectedMessage.sender.split('. Accept')[0] : 
                       (selectedMessage.sender === 'Internshala Chat' ? (() => {
                         const match = selectedMessage.content.match(/(?:internship|role|position|opportunity) at ([A-Z][A-Za-z0-9 &]+?)(?:\.|,|\n| Accept)/i) || selectedMessage.content.match(/(?:We are interested in your profile for.*?at )([A-Z][A-Za-z0-9 &]+)/i);
                         return match && match[1] ? match[1].trim() : "Internshala Chat";
                       })() : selectedMessage.sender)}
                    </span>
                    <span className="text-[10px] text-muted-foreground uppercase tracking-wider bg-white/10 px-2 py-0.5 rounded-full font-bold">
                      {selectedMessage.platform}
                    </span>
                  </div>
                  <div className="text-white font-bold tracking-tight">
                    {selectedMessage.subject}
                  </div>
                </div>
                <button onClick={() => setSelectedMessage(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                  <RefreshCw className="w-5 h-5 rotate-45" />
                </button>
              </div>
              <div className="text-xs text-muted-foreground flex gap-4">
                <span>Received: {selectedMessage.received_at ? new Date(selectedMessage.received_at).toLocaleString() : "Unknown"}</span>
                {selectedMessage.is_important && (
                  <span className="flex items-center gap-1 text-white">
                    <Star className="w-3 h-3 fill-white" />
                    Important
                  </span>
                )}
              </div>
            </div>
            <div className="p-8 flex-1 overflow-y-auto bg-[#232327]">
              <div className="text-white/90 leading-7 whitespace-pre-wrap text-base sm:text-lg font-normal tracking-wide">
                {selectedMessage.content}
              </div>
            </div>
            <div className="p-4 bg-[#232327] border-t border-white/[0.08] flex justify-end">
              <button onClick={() => setSelectedMessage(null)} className="px-6 py-2 bg-white text-black hover:bg-gray-200 transition-colors rounded-lg font-medium shadow-lg border border-white/[0.08]">
                Done
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import React, { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { profileApi, api, applicationsApi, onboardingApi } from "@/lib/api";
import { useAuth } from "@/lib/auth";
import { toast } from "sonner";
import { motion, AnimatePresence } from "framer-motion";
import { 
  User as UserIcon, 
  Briefcase, 
  GraduationCap, 
  Code, 
  Edit3, 
  Plus, 
  X, 
  Download, 
  Phone, 
  CheckCircle2,
  Send,
  Target,
  BarChart3,
  Smartphone,
  Monitor,
  Laptop,
  Trash2,
  LogOut,
  AlertTriangle,
  Loader2,
  Save,
  Calendar,
  Zap
} from "lucide-react";
import { cn } from "@/lib/utils";
import { UNIVERSAL_SKILLS } from "@/lib/skillRecommendations";

// --- Types ---
interface Session {
  id: string;
  device_name: string | null;
  device_type: string | null;
  browser: string | null;
  os: string | null;
  ip_address: string | null;
  location: string | null;
  is_current: boolean;
  is_active: boolean;
  created_at: string;
  last_used_at: string | null;
}

// --- Main Page ---
export default function ProfilePage() {
  const { user } = useAuth();
  const qc = useQueryClient();
  const [activeTab, setActiveTab] = useState("basic");

  const { data: profile, isLoading } = useQuery({
    queryKey: ["profile"],
    queryFn: () => profileApi.get().then(r => r.data),
    staleTime: 60000,
  });

  const { data: profileSkills = [] } = useQuery({
    queryKey: ["profile-skills"],
    queryFn: () => profileApi.listSkills().then(r => r.data),
    staleTime: 60000,
  });

  const { data: stats } = useQuery({
    queryKey: ["app-stats"],
    queryFn: () => applicationsApi.stats().then(r => r.data),
  });

  // Edit Basic Info State
  const [editBasic, setEditBasic] = useState(false);
  const [basicForm, setBasicForm] = useState({ 
    full_name: "", 
    professional_summary: "", 
    unique_value_proposition: "",
    career_goals: "",
    desired_roles: [] as string[],
    experience_level: "",
    location: "",
    phone: "",
    linkedin_url: "",
    github_url: "",
    portfolio_url: "",
  });

  const [automationForm, setAutomationForm] = useState({ 
    auto_apply_enabled: false,
    auto_apply_threshold: 75,
    auto_apply_daily_limit: 10,
    require_apply_approval: true,
    telegram_chat_id: "",
  });

  const [prefsForm, setPrefsForm] = useState({
    desired_roles: "",
    desired_locations: "",
    min_salary: 0,
    preferred_industries: "",
  });

  // Modal States
  const [modalType, setModalType] = useState<"experience" | "education" | "skill" | null>(null);

  // Experience Form
  const [expForm, setExpForm] = useState({
    title: "", company: "", 
    start_month: "01", start_year: "", 
    end_month: "01", end_year: "", 
    is_current: false, description: ""
  });

  // Education Form
  const [eduForm, setEduForm] = useState({
    degree: "", field: "", institution: "", graduation_year: "", gpa: ""
  });

  // Skill Form
  const [skillForm, setSkillForm] = useState({
    name: ""
  });
  const [sessionAddedSkills, setSessionAddedSkills] = useState<string[]>([]);
  const [parseFile, setParseFile] = useState<File | null>(null);
  const [editIndex, setEditIndex] = useState<number | null>(null);

  const handleDownloadInfo = () => {
    const lines = [
      "Applivo Profile Information",
      "",
      `Name: ${profile?.full_name || user?.full_name || "New Candidate"}`,
      `Email: ${user?.email || "—"}`,
      `App ID: ${user?.id || "—"}`,
      `Experience Level: ${profile?.experience_level || "—"}`,
      `Phone: ${profile?.phone || "+1 (555) 000-0000"}`,
      `Location: ${profile?.location || "Remote"}`,
      `LinkedIn: ${profile?.linkedin_url || "—"}`,
      `GitHub: ${profile?.github_url || "—"}`,
      `Portfolio: ${profile?.portfolio_url || "—"}`,
      "",
      "Generated from the Applivo profile page.",
    ];

    const blob = new Blob([lines.join("\n")], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${(profile?.full_name || user?.full_name || "applivo-profile").replace(/\s+/g, "-").toLowerCase()}.txt`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
    toast.success("Profile info downloaded");
  };

  // Mutations
  const mutUpdate = useMutation({
    mutationFn: (data: any) => profileApi.update(data),
    onSuccess: () => {
      toast.success("Profile updated!");
      setModalType(null);
      setEditIndex(null);
      setEditBasic(false);
      qc.invalidateQueries({ queryKey: ["profile"] });
      qc.invalidateQueries({ queryKey: ["profile-skills"] });
    },
    onError: () => toast.error("Update failed")
  });

  const mutAddSkill = useMutation({
    mutationFn: (data: any) => profileApi.addSkill(data),
    onSuccess: (_data, variables) => {
      toast.success("Skill added!");
      const addedName = String(variables?.name || "").trim();
      if (addedName) {
        setSessionAddedSkills((prev) => Array.from(new Set([...prev, addedName])));
      }
      setSkillForm({ name: "" });
      qc.invalidateQueries({ queryKey: ["profile"] });
      qc.invalidateQueries({ queryKey: ["profile-skills"] });
    },
    onError: () => toast.error("Failed to add skill")
  });

  const mutParseAndFill = useMutation({
    mutationFn: async (file: File) => {
      const fd = new FormData();
      fd.append("file", file);
      return onboardingApi.parseResumeAndFill(fd);
    },
    onSuccess: () => {
      toast.success("Profile updated from resume");
      setParseFile(null);
      qc.invalidateQueries({ queryKey: ["profile"] });
      qc.invalidateQueries({ queryKey: ["profile-skills"] });
    },
    onError: (err: any) => {
      const errorDetail = err?.response?.data?.detail;
      toast.error(typeof errorDetail === "string" ? errorDetail : "Failed to parse resume");
    },
  });

  const handleAddExperience = (e: React.FormEvent) => {
    e.preventDefault();
    const data = {
        ...expForm,
        start_date: expForm.start_year ? `${expForm.start_year}-${expForm.start_month}` : "",
        end_date: expForm.end_year ? `${expForm.end_year}-${expForm.end_month}` : ""
    };
    const updatedExp = [...(profile?.work_experience || [])];
    if (editIndex !== null) {
      updatedExp[editIndex] = data;
    } else {
      updatedExp.push(data);
    }
    mutUpdate.mutate({ work_experience: updatedExp });
  };

  const handleEditExperienceOpen = (index: number) => {
    const item = profile?.work_experience[index];
    const sDate = item.start_date || item.start || "";
    const sParts = sDate.split("-");
    const eDate = item.end_date || item.end || "";
    const eParts = eDate.split("-");

    setExpForm({
      title: item.title || "",
      company: item.company || "",
      start_year: sParts[0] || "",
      start_month: sParts[1] || "01",
      end_year: eParts[0] || "",
      end_month: eParts[1] || "01",
      is_current: item.is_current || false,
      description: item.description || ""
    });
    setEditIndex(index);
    setModalType("experience");
  };

  const handleDeleteExperience = (index: number) => {
    if (!window.confirm("Are you sure you want to delete this experience?")) return;
    const updatedExp = profile?.work_experience.filter((_: any, i: number) => i !== index);
    mutUpdate.mutate({ work_experience: updatedExp });
  };

  const handleAddEducation = (e: React.FormEvent) => {
    e.preventDefault();
    const updatedEdu = [...(profile?.education || [])];
    if (editIndex !== null) {
      updatedEdu[editIndex] = eduForm;
    } else {
      updatedEdu.push(eduForm);
    }
    mutUpdate.mutate({ education: updatedEdu });
  };

  const handleEditEducationOpen = (index: number) => {
    const item = profile?.education[index];
    setEduForm({
      degree: item.degree || "",
      field: item.field || "",
      institution: item.institution || "",
      graduation_year: toYearOnly(item.year || item.graduation_year),
      gpa: item.gpa || ""
    });
    setEditIndex(index);
    setModalType("education");
  };

  const handleDeleteEducation = (index: number) => {
    if (!window.confirm("Are you sure you want to delete this education?")) return;
    const updatedEdu = profile?.education.filter((_: any, i: number) => i !== index);
    mutUpdate.mutate({ education: updatedEdu });
  };

  const handleAddSkill = (e: React.FormEvent) => {
    e.preventDefault();
    const skillName = skillForm.name.trim();
    if (!skillName) return;

    const alreadyExists = profileSkills.some((s: any) => (s.name || "").toLowerCase() === skillName.toLowerCase())
      || sessionAddedSkills.some((s) => s.toLowerCase() === skillName.toLowerCase());

    if (alreadyExists) {
      toast.info("Skill already added");
      setSkillForm({ name: "" });
      return;
    }

    mutAddSkill.mutate({
      name: skillName,
      proficiency: "intermediate",
      category: "tool",
    });
  };

  const handleDeleteSkill = async (skillId: string) => {
    if (!window.confirm("Remove this skill?")) return;
    try {
      await profileApi.deleteSkill(skillId);
      toast.success("Skill removed");
      qc.invalidateQueries({ queryKey: ["profile-skills"] });
    } catch (err) {
      toast.error("Failed to remove skill");
    }
  };


  const handleEditBasicOpen = () => {
    setBasicForm({
      full_name: profile?.full_name || user?.full_name || "",
      professional_summary: profile?.professional_summary || "",
      unique_value_proposition: profile?.unique_value_proposition || "",
      career_goals: profile?.career_goals || "",
      desired_roles: profile?.desired_roles || [],
      experience_level: profile?.experience_level || "entry",
      location: profile?.location || "",
      phone: profile?.phone || "",
      linkedin_url: profile?.linkedin_url || "",
      github_url: profile?.github_url || "",
      portfolio_url: profile?.portfolio_url || "",
    });
    setEditBasic(true);
  };

  const handleEditPrefsOpen = () => {
    setPrefsForm({
      desired_roles: (profile?.desired_roles || []).join(", "),
      desired_locations: (profile?.desired_locations || []).join(", "),
      min_salary: profile?.min_salary || 0,
      preferred_industries: (profile?.preferred_industries || []).join(", "),
    });
  };

  const handleEditAutomationOpen = () => {
    setAutomationForm({
      auto_apply_enabled: profile?.auto_apply_enabled || false,
      auto_apply_threshold: profile?.auto_apply_threshold || 75,
      auto_apply_daily_limit: profile?.auto_apply_daily_limit || 10,
      require_apply_approval: profile?.require_apply_approval || true,
      telegram_chat_id: profile?.telegram_chat_id || "",
    });
  };

  React.useEffect(() => {
    if (profile) {
      if (activeTab === "preferences") handleEditPrefsOpen();
      if (activeTab === "automation") handleEditAutomationOpen();
    }
  }, [profile, activeTab]);

  const completion = profile ? Math.round(([profile.full_name, profile.professional_summary, profile.location, profile.work_experience?.length, profileSkills?.length].filter(Boolean).length / 5) * 100) : 0;

  const clampDailyLimit = (value: number) => {
    if (!Number.isFinite(value)) return 10;
    return Math.min(100, Math.max(1, Math.trunc(value)));
  };

  const formatMonthYear = (value?: string | null) => {
    if (!value) return "Not specified";
    const raw = String(value).trim();
    if (!raw) return "Not specified";
    const yyyymm = raw.match(/^(\d{4})-(\d{2})$/);
    if (yyyymm) {
      const [_, year, month] = yyyymm;
      const dt = new Date(Number(year), Number(month) - 1, 1);
      if (!Number.isNaN(dt.getTime())) {
        return dt.toLocaleDateString("en-US", { month: "short", year: "numeric" });
      }
    }
    const yearMatch = raw.match(/\b(19|20)\d{2}\b/);
    if (yearMatch) return yearMatch[0];
    return raw;
  };

  const toYYYYMM = (value?: string | null) => {
    if (!value) return "";
    const raw = String(value).trim();
    const match = raw.match(/^(\d{4})-(\d{2})$/);
    if (match) return raw;
    const yearMatch = raw.match(/\b(19|20)\d{2}\b/);
    if (yearMatch) return `${yearMatch[0]}-01`;
    return "";
  };

  const toYearOnly = (value?: string | number | null) => {
    if (!value) return "";
    const raw = String(value).trim();
    const match = raw.match(/\b(19|20)\d{2}\b/);
    return match ? match[0] : "";
  };

  if (isLoading) return (
    <div className="max-w-7xl mx-auto px-6 py-6 space-y-6">
      <div className="h-64 bg-[#232327] border border-[#1C1C24] rounded-2xl animate-pulse" />
      <div className="grid grid-cols-4 gap-6">
        {[1,2,3,4].map(i => <div key={i} className="h-24 bg-[#232327] border border-[#1C1C24] rounded-2xl animate-pulse" />)}
      </div>
    </div>
  );

  return (
    <div className="max-w-7xl mx-auto px-6 py-6 space-y-6 bg-transparent">

      {/* Page Header */}
      <div className="flex items-center gap-3 mb-4">
        <div className="p-2 bg-[#242424] border border-white/[0.08] rounded-lg">
          <UserIcon className="w-5 h-5 text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-bold text-white">Profile</h1>
          <p className="text-sm text-zinc-400 mt-1">Manage your personal information and credentials</p>
        </div>
      </div>

      {/* 1. Profile Header Card */}
      <section className="bg-[#1c1c1e] border border-[#262626] rounded-2xl p-6 shadow-sm">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div className="flex items-center gap-5">
            <div className="w-20 h-20 rounded-full border border-white/10 overflow-hidden bg-[#232327] flex items-center justify-center shrink-0">
              {profile?.avatar_url ? (
                <img src={profile.avatar_url} alt="Profile" className="w-full h-full object-cover" />
              ) : (
                <UserIcon className="w-8 h-8 text-white" />
              )}
            </div>
            <div>
              <h1 className="text-xl font-semibold text-white mb-0.5">{profile?.full_name || user?.full_name || "New Candidate"}</h1>
              <div className="flex flex-wrap items-center gap-3">
                <span className="text-xs text-[#A1A1AA]">{profile?.experience_level || "No level set"}</span>
                <span className="text-xs text-[#A1A1AA]">App ID: {user?.id.slice(0, 8)}</span>
                <div className="flex items-center gap-1.5 px-2 py-0.5 bg-white/5 border border-white/10 rounded-full">
                  <div className="w-1.5 h-1.5 rounded-full bg-green-500" />
                  <span className="text-[10px] text-white font-bold uppercase tracking-wider">{completion}% Complete</span>
                </div>
              </div>
            </div>
          </div>

          <button 
            onClick={handleDownloadInfo}
            className="bg-white text-black rounded-xl px-4 py-2 font-medium hover:bg-gray-200 transition-all flex items-center gap-2"
          >
            <Download className="w-4 h-4" />
            Download Info
          </button>
        </div>

        {/* Meta Grid */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 mt-8 pt-6 border-t border-white/10">
          <div className="space-y-1">
            <p className="text-xs text-[#A1A1AA]">Role</p>
            <p className="text-sm text-white font-medium">{profile?.experience_level ? `${profile.experience_level} Professional` : "—"}</p>
          </div>
          <div className="space-y-1">
            <p className="text-xs text-[#A1A1AA]">Phone Number</p>
            <p className="text-sm text-white font-medium">{profile?.phone || "+1 (555) 000-0000"}</p>
          </div>
          <div className="space-y-1">
            <p className="text-xs text-[#A1A1AA]">Email Address</p>
            <p className="text-sm text-white font-medium truncate">{user?.email || "—"}</p>
          </div>
          <div className="space-y-1">
            <p className="text-xs text-[#A1A1AA]">Location</p>
            <p className="text-sm text-white font-medium">{profile?.location || "Remote"}</p>
          </div>
        </div>
      </section>

      {/* 2. Resume Parse Quick Action (Top) */}
      <section className="bg-[#1c1c1e] border border-[#262626] rounded-2xl p-6 shadow-sm">
        <p className="text-sm font-semibold text-white mb-3">Update Profile From Resume</p>
        <div className="flex flex-col md:flex-row gap-3 md:items-center">
          <input
            type="file"
            accept=".pdf,application/pdf"
            onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) {
                    mutParseAndFill.mutate(file);
                }
            }}
            disabled={mutParseAndFill.isPending}
            className="text-xs text-[#A1A1AA] file:mr-3 file:rounded-lg file:border-0 file:bg-white file:px-3 file:py-2 file:text-xs file:font-semibold file:text-black hover:file:bg-zinc-200 disabled:opacity-50"
          />
          {mutParseAndFill.isPending && (
            <div className="flex items-center gap-2 text-xs text-white">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span>Reading resume...</span>
            </div>
          )}
        </div>
        <p className="text-xs text-[#A1A1AA] mt-2">Uploads are not required here. This will parse the PDF and fill your profile fields, which you can edit anytime.</p>
      </section>


      {/* 4. Tabbed Content Section */}
      <section className="space-y-6">
        <div className="bg-[#232327] border border-white/10 rounded-full p-1 flex gap-1 w-fit overflow-x-auto no-scrollbar">
          {[
            { id: "basic", label: "Basic Info", icon: UserIcon },
            { id: "experience", label: "Experience", icon: Briefcase },
            { id: "education", label: "Education", icon: GraduationCap },
            { id: "skills", label: "Skills", icon: Code },
            { id: "preferences", label: "Preferences", icon: Target },
            { id: "automation", label: "Automation", icon: Zap },
          ].map(t => (
            <button 
              key={t.id} 
              onClick={() => setActiveTab(t.id)}
              className={cn(
                "flex items-center gap-2 px-4 py-2 rounded-full text-xs font-medium transition-all whitespace-nowrap", 
                activeTab === t.id ? "bg-white text-black" : "text-[#A1A1AA] hover:text-white"
              )}
            >
              <t.icon className="w-3.5 h-3.5" /> 
              <span>{t.label}</span>
            </button>
          ))}
        </div>

        <AnimatePresence mode="wait">
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="bg-[#1c1c1e] border border-[#262626] rounded-2xl p-6 shadow-sm min-h-[400px]"
          >
            {activeTab === "basic" && (
              <div className="space-y-6">
                <div className="flex items-center justify-between">
                  <h2 className="text-lg font-semibold text-white">Basic Information</h2>
                  {!editBasic && (
                    <button onClick={handleEditBasicOpen} className="p-2 bg-[#232327] border border-white/10 rounded-xl text-white hover:bg-[#1C1C24] transition-all">
                      <Edit3 className="w-4 h-4" />
                    </button>
                  )}
                </div>

                {editBasic ? (
                  <form onSubmit={e => { e.preventDefault(); mutUpdate.mutate(basicForm); }} className="grid grid-cols-2 gap-4">
                    <div className="col-span-1 space-y-2">
                      <label className="text-xs text-[#A1A1AA]">Full Name</label>
                      <input type="text" value={basicForm.full_name} onChange={e => setBasicForm({ ...basicForm, full_name: e.target.value })} className="w-full bg-[#232327] border border-[#1C1C24] rounded-xl px-4 py-2.5 text-sm text-white focus:outline-none focus:border-white transition-all" />
                    </div>
                    <div className="col-span-1 space-y-2">
                        <label className="text-xs text-[#A1A1AA]">Experience Level</label>
                        <select value={basicForm.experience_level} onChange={e => setBasicForm({ ...basicForm, experience_level: e.target.value })} className="w-full bg-[#232327] border border-[#1C1C24] rounded-xl px-4 py-2.5 text-sm text-white focus:outline-none focus:border-white transition-all capitalize">
                            {["entry", "mid", "senior", "lead", "executive"].map(l => <option key={l} value={l}>{l}</option>)}
                        </select>
                    </div>
                    <div className="col-span-1 space-y-2">
                      <label className="text-xs text-[#A1A1AA]">Location</label>
                      <input type="text" value={basicForm.location} onChange={e => setBasicForm({ ...basicForm, location: e.target.value })} className="w-full bg-[#232327] border border-[#1C1C24] rounded-xl px-4 py-2.5 text-sm text-white focus:outline-none focus:border-white transition-all" />
