                  >
                    {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : "Continue"}
                  </button>
                </motion.form>
              ) : (
                <motion.form 
                  key="verify-form"
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: -20 }}
                  onSubmit={handleVerifySubmit} 
                  className="space-y-4 relative z-10"
