                  </div>
                </motion.form>
              )}
            </AnimatePresence>

            <div className="text-center pt-2 relative z-10">
              <p className="text-sm text-[#A1A1AA]">
                Don&apos;t have an account?{" "}
                <Link href="/register" className="text-white hover:underline font-medium">Sign up</Link>
              </p>
            </div>
          </div>
        </div>
      </motion.div>
    </main>
  );
}

