            <p className="text-[#f4f4f5] text-sm font-sans tracking-tight">
              {text}<span className="inline-block w-[2px] h-[16px] bg-[#3b82f6] ml-1 align-middle animate-[pulse_0.8s_infinite]" />
            </p>
          </div>

          {/* Bottom actions row */}
