// ============================================================================
// FLOATING PARTICLES BACKGROUND
// ============================================================================
export function FloatingParticles() {
  const particles = useMemo(
    () =>
      Array.from({ length: 20 }, (_, i) => {
        const seed = i + 1;
        const x = (seed * 37) % 100;
        const y = (seed * 53) % 100;
        const duration = 10 + ((seed * 29) % 10);
        const delay = ((seed * 13) % 50) / 10;
        const left = (seed * 41) % 100;
        const animationDelay = ((seed * 17) % 50) / 10;
        return {
          x,
          y,
          duration,
          delay,
          left,
          animationDelay,
        };
      })),
    []
  );

  return (
    <div className="absolute inset-0 overflow-hidden pointer-events-none">
      {particles.map((p, i) => (
        <motion.div
          key={i}
          className="absolute w-1 h-1 bg-violet-400/30 rounded-full"
          initial={{
            x: `${p.x}%`,
            y: `${p.y}%`,
          }}
          animate={{
            y: [null, "-100%"],
            opacity: [0, 1, 0],
          }}
          transition={{
            duration: p.duration,
            repeat: Infinity,
            delay: p.delay,
          }}
          style={{
            left: `${p.left}%`,
            animationDelay: `${p.animationDelay}s`,
          }}
        />
      ))}
    </div>
  );
}

// ============================================================================
// MATCH SCORE BADGE
// ============================================================================
interface MatchScoreBadgeProps {
  score: number;
  className?: string;
}

export function MatchScoreBadge({ score, className }: MatchScoreBadgeProps) {
  const getColor = (score: number) => {
    if (score >= 80) return "bg-emerald-500";
    if (score >= 60) return "bg-blue-500";
    if (score >= 40) return "bg-amber-500";
    return "bg-zinc-400";
  };

  const getLabel = (score: number) => {
    if (score >= 80) return "Excellent Match";
    if (score >= 60) return "Good Match";
    if (score >= 40) return "Fair Match";
    return "Low Match";
  };

  return (
    <div className={cn("flex items-center gap-2", className)}>
      <div className="relative w-10 h-10">
        <svg className="w-10 h-10 -rotate-90">
          <circle
            cx="20"
            cy="20"
            r="16"
            stroke="currentColor"
            strokeWidth="3"
            fill="none"
            className="text-zinc-100"
          />
          <motion.circle
            cx="20"
            cy="20"
            r="16"
            stroke="currentColor"
            strokeWidth="3"
            fill="none"
            className={getColor(score)}
            strokeLinecap="round"
            initial={{ strokeDasharray: 100, strokeDashoffset: 100 }}
            animate={{ strokeDashoffset: 100 - score }}
            transition={{ duration: 1, ease: "easeOut" }}
          />
        </svg>
        <span className="absolute inset-0 flex items-center justify-center text-xs font-bold">
          {Math.round(score)}
        </span>
      </div>
      <span className="text-xs font-medium text-zinc-600">{getLabel(score)}</span>
    </div>
  );
}

