const SubscriptionContext = createContext<SubscriptionContextType | null>(null);

export function SubscriptionProvider({ children }: { children: React.ReactNode }) {
  const { user, isAuthenticated } = useAuth();
  const [subscription, setSubscription] = useState<Subscription | null>(null);
  const [quota, setQuota] = useState<QuotaStatus | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const normalizePlan = (raw: unknown): PlanTier => {
    if (raw === null || raw === undefined) return "none";
    const text = String(raw).toLowerCase();
    const value = text.includes(".") ? text.split(".").pop() || "" : text;
    if (value === "starter" || value === "pro" || value === "premium") return value;
    return "none";
  };

  const normalizeStatus = (raw: unknown): string => {
    if (raw === null || raw === undefined) return "";
    const text = String(raw).toLowerCase();
    return text.includes(".") ? text.split(".").pop() || "" : text;
  };

  const normalizeSubscriptionResponse = (data: any): Subscription | null => {
    if (!data) return null;

    const candidate = data.subscription ?? data;
    if (!candidate?.plan) return null;

    const normalizedPlan = normalizePlan(candidate.plan?.value ?? candidate.plan);
    const normalizedStatus = normalizeStatus(candidate.status?.value ?? candidate.status);

    return {
      id: String(candidate.id ?? ""),
      plan: normalizedPlan,
      status: normalizedStatus,
      start_date: candidate.start_date ?? null,
      end_date: candidate.end_date ?? null,
      daily_limit: Number(candidate.daily_limit ?? 0),
    } as Subscription;
  };

  const refresh = useCallback(async () => {
    if (!isAuthenticated) return;
    try {
      const [subRes, quotaRes] = await Promise.allSettled([
        subscriptionsApi.current(),
        quotasApi.status(),
      ]);
      if (subRes.status === "fulfilled") {
        setSubscription(normalizeSubscriptionResponse(subRes.value.data));
      }
      if (quotaRes.status === "fulfilled") setQuota(quotaRes.value.data);
    } catch {
      // Not subscribed yet
    } finally {
      setIsLoading(false);
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (isAuthenticated) {
      refresh();
    } else {
      setSubscription(null);
      setQuota(null);
      setIsLoading(false);
    }
  }, [isAuthenticated, refresh]);

  useEffect(() => {
    if (!isAuthenticated) return;

    const handleFocus = () => {
      refresh();
    };

    const handleVisibilityChange = () => {
      if (!document.hidden) {
        refresh();
      }
    };

    window.addEventListener("focus", handleFocus);
    document.addEventListener("visibilitychange", handleVisibilityChange);

    const interval = window.setInterval(() => {
      refresh();
    }, 60000);

    return () => {
      window.removeEventListener("focus", handleFocus);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      window.clearInterval(interval);
    };
  }, [isAuthenticated, refresh]);

  const isSuper = user?.is_superuser ?? false;
  const hasActiveStatus = normalizeStatus(subscription?.status) === "active";
  const plan = (isSuper ? "premium" : (
    hasActiveStatus
      ? normalizePlan(subscription?.plan)
      : "none"
  )) as PlanTier;
  const isActive = isSuper || hasActiveStatus;
  const isPro = isSuper || plan === "pro" || plan === "premium";
  const isPremium = isSuper || plan === "premium";

  const canAccess = (feature: Feature): boolean => {
    if (isSuper) return true;
    if (!isActive) return false;
    return FEATURE_REQUIREMENTS[feature]?.includes(plan) ?? false;
  };

  return (
    <SubscriptionContext.Provider
      value={{
        subscription,
        quota,
        plan,
        isActive,
        isPro,
        isPremium,
        canAccess,
        isLoading,
        refresh,
      }}
    >
      {children}
    </SubscriptionContext.Provider>
  );
}

export function useSubscription() {
  const ctx = useContext(SubscriptionContext);
  if (!ctx) throw new Error("useSubscription must be used inside SubscriptionProvider");
  return ctx;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function formatDate(date: string | Date | null | undefined): string {
  if (!date) return "—";
  return new Date(date).toLocaleDateString("en-IN", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

export function formatDateTime(date: string | Date | null | undefined): string {
  if (!date) return "—";
  return new Date(date).toLocaleString("en-IN", {
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export function formatCurrency(amount: number, currency = "INR"): string {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(amount);
}

export function timeAgo(date: string | Date | null | undefined): string {
  if (!date) return "—";
  const now = new Date();
  const d = new Date(date);
  const diff = Math.floor((now.getTime() - d.getTime()) / 1000);

  if (diff < 60) return `${diff}s ago`;
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
  if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
  if (diff < 604800) return `${Math.floor(diff / 86400)}d ago`;
  return formatDate(date);
}

export function getMatchColor(score: number): string {
  if (score >= 75) return "match-high";
  if (score >= 50) return "match-medium";
  return "match-low";
}

